+static QJsonObject readConfig(const QString &path)
+{
+    QFile config(path);
+    if (!config.open(QIODevice::ReadOnly)) {
+        return {};
+    }
+    return QJsonDocument::fromJson(config.readAll()).object();
+}
+
+static Result<> securityKeyResult(QProcess *process, Result<> (*otherwise)(QProcess *))
+{
+    const auto exitCode = static_cast<ExitCode>(process->exitCode());
+
+    if (process->exitStatus() != QProcess::NormalExit) {
+        return otherwise(process);
+    }
+
+    switch (exitCode) {
+    case ExitCode::WrongPassword:
+        return Result<>::error(Error::BackendError, i18n("This security key cannot unlock the vault."));
+
+    case ExitCode::SecurityKeyError:
+        return Result<>::error(Error::CommandError,
+                               process->property("pinRequested").toBool() ? i18n("Check the PIN and touch the security key when it blinks.")
+                                                                          : i18n("Touch the security key when it blinks, and check that it is the right key."),
+                               process->readAllStandardOutput(),
+                               process->readAllStandardError());
+
+    default:
+        return otherwise(process);
+    }
+}
