-QString GocryptfsBackend::getConfigFilePath(const Device &device) const
+QProcess *GocryptfsBackend::gocryptfs(const QStringList &arguments, const QString &securityKey, const QString &pin) const
+{
+    if (securityKey.isEmpty()) {
+        return gocryptfs(arguments);
+    }
+
+    auto config = KSharedConfig::openConfig(PLASMAVAULT_CONFIG_FILE);
+    KConfigGroup backendConfig(config, "GocryptfsBackend");
+
+    // fido2-cred and fido2-assert ask for the PIN of the key on the
+    // terminal, so give them one
+    auto result = new KPtyProcess();
+    result->setPtyChannels(KPtyProcess::NoChannels);
+    result->setProgram(QStringLiteral("gocryptfs"));
+    result->setArguments(QStringList{QStringLiteral("-fido2"), securityKey} + arguments + backendConfig.readEntry("extraMountOptions", QStringList{}));
+
+    QObject::connect(result->pty(), &QIODevice::readyRead, result, [result, pin] {
+        if (result->pty()->readAll().contains("PIN")) {
+            result->setProperty("pinRequested", true);
+            result->pty()->write(pin.toUtf8() + "\n");
+        }
+    });
+
+    return result;
+}
+
+QString GocryptfsBackend::getConfigFilePath(const Device &device)
 {
     return device.data() + QStringLiteral("/gocryptfs.conf");
 }
